local u,p=arg[1],arg[2]; if not u or not p then print("Usage: http-save <url> <file>") return end; local ok,r=http.checkURL(u); if not ok then print("Denied: "..tostring(r)) return end; local h,e=http.get(u); if not h then print("Failed: "..tostring(e)) return end; local c=h.getResponseCode(); local d=h.readAll(); h.close(); if c<200 or c>=300 then print("HTTP "..c) return end; local f=fs.open(p,"w"); f.write(d); f.close(); print("Saved "..#d.." bytes.")